function ClientForm({client,clients=[],creator,employees,busy,onSave}:{clients?:Client[];client:Client|null;creator?:Employee;employees:Employee[];busy:boolean;onSave:(c:any)=>Promise<void>}){
 const [phone,setPhone]=useState(client?.phone||"");const duplicate=!client&&normalizePhone(phone)?clients.find(c=>c.phone===normalizePhone(phone)):undefined;
 const [address,setAddress]=useState(client?.address||"");const [addressParts,setAddressParts]=useState<AddressParts>(client?.addressParts||{...emptyAddressParts,city:client?.city||""});const [owner,setOwner]=useState(client?client.owner||"free":(creator?.role==="operator"?creator.id:"free"));return <form className="stack" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void onSave({claimId:duplicate?.id,name:duplicate?.name||f.get("name"),phone,city:addressParts.city,address,addressParts,source:client?.source||"Вручную",owner:owner==="free"?"":owner});}}><div className="form-grid"><Field label="ФИО клиента"><input required={!duplicate} name="name" maxLength={150} defaultValue={client?.name}/></Field>{(!client||!hideClientPhone(creator?.role))&&<Field label="Телефон"><input required name="phone" type="tel" placeholder="+7 900 000-00-00" value={phone} onChange={e=>{setPhone(e.target.value);if(!client)setOwner("free");}}/></Field>}<Field label="Ответственный менеджер">{creator?.role==="operator"?<input disabled value={employees.find(e=>e.id===owner)?.login||"Общая база"}/>:<Pick label="Ответственный менеджер" value={owner} onChange={setOwner} options={[{value:"free",label:"Общая база"},...employees.filter(e=>e.role==="operator"&&(creator?.role!=="department_head"||!!creator.department&&e.department===creator.department)).map(e=>({value:e.id,label:e.login}))]}/>}</Field></div><AddressField value={address} parts={addressParts} onChange={(v,p)=>{setAddress(v);setAddressParts(p||emptyAddressParts);}} disabled={busy}/><p className="muted">{client?.addressOriginal&&`Из Excel: ${client.addressOriginal}`}</p>{client?.addressReview&&<p className="orange">Адрес требует проверки: исходный текст сохранён.</p>}<>{duplicate&&<p role="status">Клиент уже есть в базе: {duplicate.name}. {duplicate.owner?`Закреплён за ${employees.find(e=>e.id===duplicate.owner)?.login||duplicate.owner}`:"Свободен. Выберите логин оператора для передачи."}</p>}{(!client||owner!==(client.owner||"free"))&&owner!=="free"&&<p className="muted">При передаче оператору клиент закрепляется на 24 часа. Если за это время оператор не создаст заказ, клиент вернётся на первый лист базы.</p>}</><button disabled={busy||!!duplicate?.owner||!!duplicate&&owner==="free"} className="primary" type="submit"><Check size={16}/>{client?"Сохранить данные":duplicate?"Передать оператору":"Добавить клиента"}</button></form>
}
function History({state,clientId,orderId}:{state:State;clientId:string;orderId?:string}){const events=state.events.filter(e=>e.clientId===clientId&&(!orderId||e.orderId===orderId)).sort((a,b)=>b.at.localeCompare(a.at));return <section className="history"><h3>История взаимодействий <span>{events.length}</span></h3>{events.map(e=><div className="history-event" key={e.id}><span className="history-dot"/><div><p>{e.text}</p><small>{stamp(e.at)} · {e.actor}</small></div></div>)}{!events.length&&<p className="muted">История пока пуста</p>}</section>}
function ClientDetail({client,creator,state,busy,mutate,openOrder,newOrder}:{client:Client;creator:Employee;state:State;busy:boolean;mutate:(d:any)=>Promise<boolean>;openOrder:(id:string)=>void;newOrder:()=>void}){return <div className="stack"><div className="detail-hero"><span className="avatar">{initials(client.name)}</span><div>{!hideClientPhone(creator.role)&&<b>{client.phone}</b>}<p>{client.source} · {client.id}</p></div><span className="badge mint">{client.owner?`Закрепление: ${stamp(client.assignedUntil)}`:"Общая база"}</span></div><ClientForm client={client} creator={creator} employees={state.employees} busy={busy} onSave={async data=>{await mutate({action:"updateClient",id:client.id,version:client.version,client:data});}}/><section>{client.orderRequest&&<p className="notice">{client.orderRequest.status==="approved"?"Получено разрешение на один дополнительный заказ.":client.orderRequest.status==="rejected"?"Запрос на дополнительный заказ отклонён.":"Запрос на дополнительный заказ ожидает решения."}</p>}<div className="section-title"><h3>Заказы клиента</h3><button className="text-button" disabled={busy} onClick={newOrder}><Plus size={16}/>Новый заказ</button></div>{state.orders.filter(o=>o.clientId===client.id).map(o=><button className="order-mini" key={o.id} onClick={()=>openOrder(o.id)}><div><b>{o.id}</b><small>{statuses[o.status]}{o.extra?" · После доп. проверки":""}</small></div><strong>{money(total(o))}</strong><ChevronRight size={16}/></button>)}</section></div>}
