 const [waybillComment,setWaybillComment]=useState(o.waybillComment||"");const [downloading,setDownloading]=useState(false);
 async function downloadWaybill(){if(o.courierRepackRequest&&!o.courierRepackRequest.completedAt){toast.error('Сначала оператор или администратор должен сохранить правки корзины после приёма посылки');return;}setDownloading(true);try{const r=await fetch(`/api/warehouse/waybill?actorId=${encodeURIComponent(employee.id)}&orderId=${encodeURIComponent(o.id)}`);if(!r.ok){const d=await r.json() as {error?:string};throw Error(d.error||"Не удалось скачать бланк");}const {downloadWaybillPdf}=await import("@/lib/waybill-pdf");await downloadWaybillPdf(await r.json());if(!o.packingWaybillAt)await mutate({action:"markPackingWaybill",id:o.id,version:o.version});}catch(e){toast.error(e instanceof Error?e.message:"Ошибка скачивания");}finally{setDownloading(false);}}
