  const [reviewChange,setReviewChange]=useState<Record<string,unknown>|null>(null);
  const saveOrderData=(data:Record<string,unknown>)=>{if(cdekReviewOnDeliveryChange(o,delivery)){setReviewChange(data);return;}void mutate(data);};
