function NewOrder({state,creator,initialClient,busy,onSave,requestOrder}:{requestOrder:(clientId:string)=>Promise<boolean>;state:State;creator:Employee;initialClient:string;busy:boolean;onSave:(d:any)=>Promise<void>}){
 const availableClients=creator.role==="operator"||creator.role==="department_head"?assignedClients(state.clients,state.employees,creator):state.clients;
 const startingClient=availableClients.find(c=>c.id===initialClient)||availableClients[0];
 const [clientId,setClientId]=useState(startingClient?.id||"");
 const [address,setAddress]=useState(startingClient?.address||"");
 const [addressParts,setAddressParts]=useState<AddressParts>(startingClient?.addressParts||emptyAddressParts);
 const [delivery,setDelivery]=useState<DeliveryMethod>("");
 const [items,setItems]=useState<Item[]>([{name:"",quantity:1,price:0}]);
 const [comment,setComment]=useState("");
 const addressReview=useOrderAddressReview(clientId,address,addressParts,busy,"Создать заказ");
 const client=availableClients.find(c=>c.id===clientId);
 const request=client?.orderRequest;
 const approved=request?.status==="approved"&&request.manager===client?.owner&&(request.actorId===creator.id||creator.role==="admin");
 const blocked=hasActiveOrder(state.orders,clientId)&&!approved;
 function save(addressConfirmed=false){
  if(busy||blocked||!client)return;
  void onSave({clientId,delivery,address,addressParts,items,comment,addressConfirmed});
 }
 function submit(e:FormEvent){
  e.preventDefault();if(busy||blocked||!client)return;
  addressReview.review(save);
 }
 return <><form className="stack" onSubmit={submit}>{!availableClients.length&&<p className="notice">Нет доступных клиентов. Попросите руководителя назначить вам клиента.</p>}<Field label="Клиент"><Pick label="Клиент заказа" value={clientId} onChange={id=>{addressReview.reset();setClientId(id);setAddressParts(availableClients.find(c=>c.id===id)?.addressParts||emptyAddressParts);setAddress(availableClients.find(c=>c.id===id)?.address||"");}} options={availableClients.map(c=>({value:c.id,label:c.name+(hideClientPhone(creator.role)?"":" · "+c.phone),muted:hasActiveOrder(state.orders,c.id)}))}/></Field><Field label="Ответственный менеджер"><input readOnly disabled={creator.role==="operator"} value={creator.role==="operator"?creator.login:state.employees.find(e=>e.id===availableClients.find(c=>c.id===clientId)?.owner)?.login||"Сначала назначьте менеджера клиенту"}/></Field><DeliveryField value={delivery} onChange={setDelivery} disabled={busy}/><div ref={addressReview.ref}><AddressField value={address} parts={addressParts} warnings={addressReview.warnings} onChange={(v,p)=>{addressReview.reset();setAddress(v);setAddressParts(p||emptyAddressParts);}} disabled={busy}/></div><Basket items={items} setItems={setItems}/><Field label="Комментарий менеджера"><textarea value={comment} onChange={e=>setComment(e.target.value)} rows={2}/></Field><>{blocked&&<div className="notice"><div><p>У клиента есть заказ в статусе «Новый», «Принят» или «Отправлен». Для нового заказа нужно разрешение руководителя отдела.</p>{request?.status==="pending"?<p>Запрос ожидает решения администратора или руководителя. Ответ появится в колокольчике — можно закрыть форму и продолжить работу.</p>:<><p>{request?.status==="rejected"?"Предыдущий запрос отклонён.":""}</p><button type="button" className="secondary" disabled={busy} onClick={()=>requestOrder(clientId)}>Запросить оформление</button></>}</div></div>}{approved&&<p className="notice">Получено разрешение на один дополнительный заказ.</p>}</><button disabled={busy||!clientId||blocked} className="primary">Создать заказ</button></form>
 {addressReview.dialog}</>;
}
function EmployeeForm({employee:e,creator,busy,onSave,personalAuth,state,onDelete}:{state:State;onDelete:(mode:string,targetId:string)=>Promise<void>;personalAuth:boolean;employee:Employee|null;creator:Employee;busy:boolean;onSave:(d:any)=>Promise<void>}){const [accessEnabled,setAccessEnabled]=useState(e?!!e.accessEnabled:true);const managed=["department_head","chief_logistic"].includes(creator.role);const [role,setRole]=useState(managed?(creator.role==="chief_logistic"?"logistic":"operator"):e?.role||"operator");const [department,setDepartment]=useState(managed?creator.department||"":e?.department||"");return <form className="stack" onSubmit={event=>{event.preventDefault();if(needsDepartment(role)&&!department){toast.error("Выберите отдел");return;}const f=new FormData(event.currentTarget);void onSave({name:f.get("name"),alias:f.get("alias"),login:f.get("login"),skLogin:f.get("skLogin"),salary:Number(f.get("salary")),bonus:Number(f.get("bonus")),role,baseAccess:f.get("baseAccess")||e?.baseAccess||"both",department:needsDepartment(role)?department:undefined,...(personalAuth?{accessEnabled,password:f.get("password")||undefined}:{})});}}><div className="form-grid"><Field label="ФИО"><input name="name" required defaultValue={e?.name}/></Field><Field label="Псевдоним"><input name="alias" defaultValue={e?.alias}/></Field><Field label="Логин CRM"><input name="login" required defaultValue={e?.login}/></Field><Field label="Логин Скорозвон"><input name="skLogin" defaultValue={e?.skLogin}/></Field><Field label="Оклад, ₽"><input name="salary" type="number" min="0" step="0.01" defaultValue={e?.salary||0}/></Field><Field label="Бонус, %"><input name="bonus" type="number" min="0" max="100" step="0.1" defaultValue={e?.bonus||0}/></Field></div>{needsDepartment(role)&&<Field label="Отдел *">{managed?<input disabled value={department?departments[department as keyof typeof departments]:"Отдел руководителю не назначен"}/>:<Pick label="Отдел сотрудника" value={department} onChange={setDepartment} options={Object.entries(departments).map(([value,label])=>({value,label}))}/>}</Field>}{role==="operator"&&<Field label="База клиентов"><select name="baseAccess" defaultValue={e?.baseAccess||"both"}><option value="M">М</option><option value="J">Ж</option><option value="both">М и Ж</option></select></Field>}<Field label="Роль">{managed?<input disabled value={creator.role==="chief_logistic"?"Логист":"Оператор"}/>:<Pick label="Роль сотрудника" value={role} onChange={v=>setRole(v as any)} options={Object.entries(roles).map(([value,label])=>({value,label}))}/>}</Field>{managed&&needsDepartment(role)&&!department&&<p role="alert">Попросите администратора назначить вам отдел.</p>}{personalAuth&&<fieldset className="stack"><legend>Вход в CRM</legend><label><input type="checkbox" checked={accessEnabled} disabled={e?.id===creator.id} onChange={event=>setAccessEnabled(event.target.checked)}/> Разрешить вход</label>{accessEnabled&&<Field label={e?.hasPassword?"Новый пароль (оставьте пустым, чтобы сохранить текущий)":"Пароль"}><input type="password" name="password" autoComplete="new-password" minLength={12} maxLength={128} required={!e?.hasPassword}/></Field>}<p className="muted">Пароль — не менее 12 символов. После смены пароля прежние сеансы завершатся.</p></fieldset>}<button disabled={busy||(needsDepartment(role)&&!department)} className="primary">Сохранить сотрудника</button>{e&&<EmployeeRemoval employee={e} creator={creator} state={state} busy={busy} onDelete={onDelete}/>}</form>}
function SettingsView({actorId,isAdmin,state,busy,mutate}:{actorId:string;isAdmin:boolean;state:State;busy:boolean;mutate:(d:any)=>Promise<boolean>}){const [integration,setIntegration]=useState<string|null>(null);return <div className="settings-grid"><section className="settings-card"><Gem/><h2>Закрепление клиентов</h2><p>Лист К: закрепление сохраняется при активных заказах и 5 недель после последнего выкупа. Затем клиент переходит в П. При отмене или возврате без других действующих заказов — в исходный лист.</p><p>Проверяется автоматически при открытии CRM и после действий. В открытой CRM срок проверяется каждую минуту. Индивидуальные сроки задаются в настройках Базы клиентов.</p></section><section className="settings-card"><Link2/><h2>Интеграции</h2><p>Выберите сервис, чтобы открыть подключение и настройки.</p><div className="integration-tiles">{["DaData","СДЭК","MainSMS","Скорозвон","Замена телефона","Интеграция с ЛВ Склад"].map(name=><button type="button" className="integration-tile" key={name} onClick={()=>setIntegration(name)} aria-haspopup="dialog"><strong>{name}</strong><span className="integration-tile-caption">Подключение и настройки</span><span className="integration-tile-icon"><Link2 size={26}/></span></button>)}</div></section><Dialog open={!!integration} onOpenChange={open=>{if(!open)setIntegration(null);}}><DialogContent className="form-dialog integration-dialog"><DialogHeader><DialogTitle>{integration}</DialogTitle><DialogDescription>Подключение, описание и настройки интеграции</DialogDescription></DialogHeader><div className="stack">{integration==="DaData"&&<><DadataSettings actorId={actorId} isAdmin={isAdmin}/>{isAdmin&&<button className="secondary" disabled={busy} onClick={()=>mutate({action:"normalizeImportedAddresses"})}>{busy?"Обработка адресов…":"Разобрать адреса текущих клиентов из Excel"}</button>}</>}{integration==="MainSMS"&&<MainSmsSettings actorId={actorId}/>} {integration==="СДЭК"&&<CdekSettings actorId={actorId} isAdmin={isAdmin}/>} {integration==="Скорозвон"&&<SkorozvonSettings actorId={actorId}/>}{integration==="Интеграция с ЛВ Склад"&&isAdmin&&<LvWarehouseSettings actorId={actorId}/>}{integration==="Замена телефона"&&<><label className="packing-ready"><input type="checkbox" role="switch" checked={false} disabled aria-describedby="phone-replacement-status"/>Подменять телефон при выгрузке в СДЭК</label><p id="phone-replacement-status" className="notice">Выключено. В СДЭК передаётся реальный телефон из карточки клиента. Включение станет доступно после подключения сервиса подмены.</p><p>После подключения администратор сможет выбирать: выключено — реальные номера, включено — подменные. Логист не выбирает и не изменяет номер для выгрузки.</p><p className="muted">Предварительная схема: CRM → сервис подмены → СДЭК. Окончательный порядок передачи заказа и замены номера определим после выбора сервиса.</p></>}</div></DialogContent></Dialog></div>}
function download(blob:Blob,name:string){const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
type ImportSheet={name:string;rows:any[];invalid:number;selected:boolean};
function ImportForm({busy,onImport}:{busy:boolean;onImport:(rows:any[])=>Promise<void>}){const [sheets,setSheets]=useState<ImportSheet[]>([]);const [reading,setReading]=useState(false);const [error,setError]=useState("");const [filename,setFilename]=useState("");
 async function read(file:File){setError("");setSheets([]);setFilename(file.name);if(!/\.xlsx$/i.test(file.name)||file.size>10*1024*1024){setError("Нужен файл .xlsx размером до 10 МБ");return;}setReading(true);try{const ExcelJS=(await import("exceljs")).default;const wb=new ExcelJS.Workbook();await wb.xlsx.load(await file.arrayBuffer());const result:ImportSheet[]=[];wb.eachSheet(sh=>{const header:string[]=[];sh.getRow(1).eachCell((cell,col)=>{header[col]=cell.text.toLowerCase().trim();});const find=(names:string[])=>header.findIndex(h=>names.includes(h));const name=find(["фио","имя","клиент","name","фио клиента"]),phone=find(["телефон","номер телефона","phone","мобильный телефон"]),city=find(["город","city"]),address=find(["адрес","адрес доставки","address"]);if(name<0||phone<0){result.push({name:sh.name,rows:[],invalid:Math.max(0,sh.rowCount-1),selected:false});return;}const rows:any[]=[];let invalid=0;sh.eachRow((row,n)=>{if(n===1)return;const fullName=row.getCell(name).text.trim(),tel=normalizePhone(row.getCell(phone).text);if(!fullName||!tel){invalid++;return;}rows.push({name:fullName,phone:tel,city:"",address:(address>0?row.getCell(address).text.trim():"")||(city>0?row.getCell(city).text.trim():""),source:`${file.name} · ${sh.name}`,owner:""});});result.push({name:sh.name,rows,invalid,selected:!!rows.length});});setSheets(result);}catch{setError("Не удалось прочитать Excel. Проверьте формат и отсутствие пароля.");}finally{setReading(false);}}
 const rows=sheets.filter(s=>s.selected).flatMap(s=>s.rows);return <div className="stack"><label className="upload-zone"><FileSpreadsheet size={30}/><b>{reading?"Читаем листы…":filename||"Выберите Excel-файл"}</b><span>Первая строка: ФИО, Телефон, Город, Адрес</span><input aria-label="Excel-файл клиентов" type="file" accept=".xlsx" disabled={reading||busy} onChange={e=>{if(e.target.files?.[0])void read(e.target.files[0]);}}/></label>{error&&<p role="alert" className="orange">{error}</p>}{sheets.map((s,i)=><label className="import-sheet" key={s.name}><Checkbox checked={s.selected} disabled={!s.rows.length||busy} onCheckedChange={checked=>setSheets(sheets.map((x,j)=>i===j?{...x,selected:!!checked}:x))}/><b>{s.name}</b><span>{s.rows.length} клиентов</span>{s.invalid>0&&<small className="orange">Не будут загружены: {s.invalid} · проверьте имя, телефон и заголовки</small>}</label>)}{rows.length>0&&<><div className="import-preview"><Table><TableHeader><TableRow><TableHead>Клиент</TableHead><TableHead>Телефон</TableHead><TableHead>Источник</TableHead></TableRow></TableHeader><TableBody>{rows.slice(0,4).map((r,i)=><TableRow key={i}><TableCell>{r.name}</TableCell><TableCell>{r.phone}</TableCell><TableCell>{r.source}</TableCell></TableRow>)}</TableBody></Table></div><p className="muted">Клиенты попадут в общую базу. Дубли по телефону будут пропущены. Адрес берётся из «Адрес» или «Город» и разбирается ДаДатой (0,20 ₽ за запись). Нераспознанный текст сохраняется. До 1000 строк за импорт.</p></>}<button disabled={busy||reading||!rows.length||rows.length>1000} className="primary" onClick={()=>onImport(rows)}><Upload size={16}/>Импортировать {rows.length?rows.length:""} клиентов</button></div>
}
